insert into public.content_items (type, category, recommended_time, translations, is_active) values
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Yaptığım işlerin kötülüğünden de henüz yapmadığım işlerin kötülüğünden de sana sığınırım!", "source": "Müslim, Zikir, 65"}, "en": {"content": "Allah’ım! Yaptığım işlerin kötülüğünden de henüz yapmadığım işlerin kötülüğünden de sana sığınırım!", "source": "Müslim, Zikir, 65"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbim! Girilecek yere doğrulukla girmemi, çıkılacak yerden de doğrulukla çıkmamı sağla, bana tarafından yardımcı bir güç ver.", "source": "İsrâ, 17/80"}, "en": {"content": "Rabbim! Girilecek yere doğrulukla girmemi, çıkılacak yerden de doğrulukla çıkmamı sağla, bana tarafından yardımcı bir güç ver.", "source": "İsrâ, 17/80"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Sana teslim olan bir kalp, doğru sözlü bir dil ve dosdoğru bir ahlak istiyorum.", "source": "Hâkim, Deavât, No: 1872"}, "en": {"content": "Allah’ım! Sana teslim olan bir kalp, doğru sözlü bir dil ve dosdoğru bir ahlak istiyorum.", "source": "Hâkim, Deavât, No: 1872"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ın gazabından, kullarının şerrinden, şeytanların vesveselerinden ve (onların) bana uğramalarından Allah’ın tam kelimelerine sığınırım.", "source": "Ebu Davud, Tıb, 19"}, "en": {"content": "Allah’ın gazabından, kullarının şerrinden, şeytanların vesveselerinden ve (onların) bana uğramalarından Allah’ın tam kelimelerine sığınırım.", "source": "Ebu Davud, Tıb, 19"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım, nefsime takvasını ver, onu temizle, onu temizleyenlerin en hayırlısı sensin. Onun velisi (sahibi) ve mevlası (efendisi) sensin.", "source": "Müslim, Zikir, Dua, Tevbe ve İstiğfar, 73"}, "en": {"content": "Allah’ım, nefsime takvasını ver, onu temizle, onu temizleyenlerin en hayırlısı sensin. Onun velisi (sahibi) ve mevlası (efendisi) sensin.", "source": "Müslim, Zikir, Dua, Tevbe ve İstiğfar, 73"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Müslümanlar olarak canımızı al, bizi Müslümanlar olarak dirilt, rezil olmadan ve fitneye uğramadan salih kullarının arasına dâhil eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "Allah’ım! Müslümanlar olarak canımızı al, bizi Müslümanlar olarak dirilt, rezil olmadan ve fitneye uğramadan salih kullarının arasına dâhil eyle.", "source": "Hâkim, Deavât, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Allah’ım!) Zenginlikle imtihan edilmenin kötülüğünden sana sığınırım. Fakirlikle imtihan edilmenin kötülüğünden de sana sığınırım.", "source": "Buhârî, Deavât, 39"}, "en": {"content": "(Allah’ım!) Zenginlikle imtihan edilmenin kötülüğünden sana sığınırım. Fakirlikle imtihan edilmenin kötülüğünden de sana sığınırım.", "source": "Buhârî, Deavât, 39"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Sen rahmetin ve ilminle her şeyi kuşattın. Tövbe edenleri ve yolundan gidenleri bağışla, onları cehennem azabından koru!", "source": "Mü’min, 40/7"}, "en": {"content": "Ey Rabbimiz! Sen rahmetin ve ilminle her şeyi kuşattın. Tövbe edenleri ve yolundan gidenleri bağışla, onları cehennem azabından koru!", "source": "Mü’min, 40/7"}}',true),
('prayer','prayer','morning','{"tr": {"content": "Allah’ım! Senin iznin ve yardımınla sabahladık ve akşamladık. Yine senin izin ve yardımınla yaşar ve ölürüz. Sonunda dönüş yalnız sanadır.", "source": "Ebu Davud, Edeb, 110"}, "en": {"content": "Allah’ım! Senin iznin ve yardımınla sabahladık ve akşamladık. Yine senin izin ve yardımınla yaşar ve ölürüz. Sonunda dönüş yalnız sanadır.", "source": "Ebu Davud, Edeb, 110"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bana kendi sevgini ve senin yanında sevgisi bana fayda verecek kimsenin sevgisini ver.", "source": "Tirmizî, Deavât, 73"}, "en": {"content": "Allah’ım! Bana kendi sevgini ve senin yanında sevgisi bana fayda verecek kimsenin sevgisini ver.", "source": "Tirmizî, Deavât, 73"}}',true),
('prayer','hope','any','{"tr": {"content": "Ey insanların Rabbi! Rahatsızlığı gider! Şifa veren sensin. Senin vereceğin şifadan başka şifa yoktur. Öyle bir şifa ver ki ardında hiç hastalık izi bırakmasın.", "source": "Müslim, Selâm, 47"}, "en": {"content": "Ey insanların Rabbi! Rahatsızlığı gider! Şifa veren sensin. Senin vereceğin şifadan başka şifa yoktur. Öyle bir şifa ver ki ardında hiç hastalık izi bırakmasın.", "source": "Müslim, Selâm, 47"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sen affedicisin, Kerim’sin, affı seversin, beni affet.", "source": "Tirmizî, Deavât, 84"}, "en": {"content": "Allah’ım! Sen affedicisin, Kerim’sin, affı seversin, beni affet.", "source": "Tirmizî, Deavât, 84"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Cehenneme götüren fitneden, cehennemin azabından, zenginliğin ve fakirliğin şerrinden sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "Allah’ım! Cehenneme götüren fitneden, cehennemin azabından, zenginliğin ve fakirliğin şerrinden sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Ayakta iken beni İslam ile koru, otururken beni İslam ile koru, uyurken beni İslam ile koru, hakkımda hiçbir düşman ve hasetçinin isteğini yerine getirme.", "source": "İbn Hibban, Ed’ıye, No: 934"}, "en": {"content": "Allah’ım! Ayakta iken beni İslam ile koru, otururken beni İslam ile koru, uyurken beni İslam ile koru, hakkımda hiçbir düşman ve hasetçinin isteğini yerine getirme.", "source": "İbn Hibban, Ed’ıye, No: 934"}}',true),
('prayer','hope','any','{"tr": {"content": "Rabbimiz! Bize katından rahmet gönder ve bize içinde bulunduğumuz durumdan bir çıkış yolu göster!", "source": "Kehf, 18/10"}, "en": {"content": "Rabbimiz! Bize katından rahmet gönder ve bize içinde bulunduğumuz durumdan bir çıkış yolu göster!", "source": "Kehf, 18/10"}}',true),
('prayer','worship','any','{"tr": {"content": "Allah’ım! Ey Rabbimiz ve ey her şeyin Rabbi! Beni ve ailemi dünya ve ahirette her an sana ihlasla bağlı kıl. Ey yücelik ve ikram sahibi!...", "source": "Ebû Dâvûd, Vitr, 25"}, "en": {"content": "Allah’ım! Ey Rabbimiz ve ey her şeyin Rabbi! Beni ve ailemi dünya ve ahirette her an sana ihlasla bağlı kıl. Ey yücelik ve ikram sahibi!...", "source": "Ebû Dâvûd, Vitr, 25"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Ey Rabbim! Gerek bana gerekse anne-babama verdiğin nimete şükretmeye ve hoşnut olacağın iyi işler yapmaya beni muvaffak kıl. Rahmetinle beni iyi kullarının arasına kat!", "source": "Neml, 27/19"}, "en": {"content": "Ey Rabbim! Gerek bana gerekse anne-babama verdiğin nimete şükretmeye ve hoşnut olacağın iyi işler yapmaya beni muvaffak kıl. Rahmetinle beni iyi kullarının arasına kat!", "source": "Neml, 27/19"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Günahlarımızdan ve işimizdeki aşırılıklardan ötürü bizi bağışla, sebatımızı arttır, kâfir topluluğa karşı bize yardım et!", "source": "Âl-i İmrân, 3/147"}, "en": {"content": "Rabbimiz! Günahlarımızdan ve işimizdeki aşırılıklardan ötürü bizi bağışla, sebatımızı arttır, kâfir topluluğa karşı bize yardım et!", "source": "Âl-i İmrân, 3/147"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Gidip ebedî yaşayacağım ahiret hayatımı benim için hayırlı eyle. Hayatımda her türlü hayrı ziyadesiyle ihsan eyle. Ölümümü de her türlü şerlerden muhafaza eyle.", "source": "Müslim, Duâ, 71"}, "en": {"content": "Allah’ım! Gidip ebedî yaşayacağım ahiret hayatımı benim için hayırlı eyle. Hayatımda her türlü hayrı ziyadesiyle ihsan eyle. Ölümümü de her türlü şerlerden muhafaza eyle.", "source": "Müslim, Duâ, 71"}}',true),
('prayer','worship','any','{"tr": {"content": "Rabbim! Tövbemi kabul et, günahımı temizle, duamı kabul buyur, delilimi sabit kıl, dilimi doğru yap, kalbime hidayet ver, göğsümün kin ve hasedini çıkar.", "source": "Tirmizî, Deavât, 114"}, "en": {"content": "Rabbim! Tövbemi kabul et, günahımı temizle, duamı kabul buyur, delilimi sabit kıl, dilimi doğru yap, kalbime hidayet ver, göğsümün kin ve hasedini çıkar.", "source": "Tirmizî, Deavât, 114"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kıyamet gününde cennet, korku gününde güven istiyorum. Allah’ım! Verdiğin ve vermediğin şeylerin şerrinden sana sığınıyorum.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "Allah’ım! Kıyamet gününde cennet, korku gününde güven istiyorum. Allah’ım! Verdiğin ve vermediğin şeylerin şerrinden sana sığınıyorum.", "source": "Hâkim, Deavât, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kulağımın kötülüğünden, gözümün kötülüğünden, dilimin kötülüğünden, kalbimin kötülüğünden, tenimin kötülüğünden sana sığınırım.", "source": "Nesâî, İstiâze, 4"}, "en": {"content": "Allah’ım! Kulağımın kötülüğünden, gözümün kötülüğünden, dilimin kötülüğünden, kalbimin kötülüğünden, tenimin kötülüğünden sana sığınırım.", "source": "Nesâî, İstiâze, 4"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sen yardım istenilensin, dualar ancak sana ulaşır, duaları sen kabul edersin, güç ve kuvvet ancak Allah ile birlikte vardır.", "source": "Tirmizî, Deavât, 94"}, "en": {"content": "Allah’ım! Sen yardım istenilensin, dualar ancak sana ulaşır, duaları sen kabul edersin, güç ve kuvvet ancak Allah ile birlikte vardır.", "source": "Tirmizî, Deavât, 94"}}',true),
('prayer','purpose','any','{"tr": {"content": "(Allah’ım!) Beni güzel ahlaka eriştir. Senden başka güzel ahlaka eriştirecek yoktur. Kötü ahlakı benden uzaklaştır. Senden başka kötü ahlakı benden uzaklaştıracak yoktur!", "source": "Müslim, Müsâfirîn, 201"}, "en": {"content": "(Allah’ım!) Beni güzel ahlaka eriştir. Senden başka güzel ahlaka eriştirecek yoktur. Kötü ahlakı benden uzaklaştır. Senden başka kötü ahlakı benden uzaklaştıracak yoktur!", "source": "Müslim, Müsâfirîn, 201"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Mal, aile, çocuk olarak insanlara verdiklerinin hayırlısını dilerim, sapıtan ve saptıranları değil.", "source": "Tirmizî, Deavât, 124"}, "en": {"content": "Allah’ım! Mal, aile, çocuk olarak insanlara verdiklerinin hayırlısını dilerim, sapıtan ve saptıranları değil.", "source": "Tirmizî, Deavât, 124"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Bizi sabırla donat, bize sebat ver ve inkârcı topluluğa karşı bize yardım et.", "source": "Bakara, 2/250"}, "en": {"content": "Rabbimiz! Bizi sabırla donat, bize sebat ver ve inkârcı topluluğa karşı bize yardım et.", "source": "Bakara, 2/250"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sevgini, seni seven kimsenin sevgisini ve sevgine ulaştıracak ameli istiyorum. Allah’ım! Sevgini, bana canımdan, ailemden ve soğuk sudan daha sevimli eyle.", "source": "Tirmizî, Deavât, 74"}, "en": {"content": "Allah’ım! Sevgini, seni seven kimsenin sevgisini ve sevgine ulaştıracak ameli istiyorum. Allah’ım! Sevgini, bana canımdan, ailemden ve soğuk sudan daha sevimli eyle.", "source": "Tirmizî, Deavât, 74"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Her işimin koruyucusu olan dinim ile beni ıslah eyle, kurtuluşa erdir. İçinde yaşadığım, geçimimi sağladığım dünyamı benim için ıslah eyle, hayırlı kıl.", "source": "Müslim, Duâ, 71"}, "en": {"content": "Allah’ım! Her işimin koruyucusu olan dinim ile beni ıslah eyle, kurtuluşa erdir. İçinde yaşadığım, geçimimi sağladığım dünyamı benim için ıslah eyle, hayırlı kıl.", "source": "Müslim, Duâ, 71"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Dinim, dünyam, ailem ve malım hakkında af ve afiyet istiyorum.", "source": "Hâkim, Deavât, No: 1902"}, "en": {"content": "Allah’ım! Dinim, dünyam, ailem ve malım hakkında af ve afiyet istiyorum.", "source": "Hâkim, Deavât, No: 1902"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım, cimrilikten sana sığınırım, korkaklıktan sana sığınırım, ömrün en rezil zamanına kalmaktan sana sığınırım.", "source": "Buhârî, Deavât, 37"}, "en": {"content": "Allah’ım, cimrilikten sana sığınırım, korkaklıktan sana sığınırım, ömrün en rezil zamanına kalmaktan sana sığınırım.", "source": "Buhârî, Deavât, 37"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Beni, iyilik yaptıkları zaman sevinç duyan, kötülük yaptıkları zaman da bağışlanma dileyen kullarından eyle.", "source": "İbn Mâce, Edeb, 57"}, "en": {"content": "Allah’ım! Beni, iyilik yaptıkları zaman sevinç duyan, kötülük yaptıkları zaman da bağışlanma dileyen kullarından eyle.", "source": "İbn Mâce, Edeb, 57"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kötü ahlaktan, nefsani arzulardan, kötü işlerden ve ayıp şeylerden beni uzaklaştır.", "source": "İbn Hibban, Ed’ıye, No: 960"}, "en": {"content": "Allah’ım! Kötü ahlaktan, nefsani arzulardan, kötü işlerden ve ayıp şeylerden beni uzaklaştır.", "source": "İbn Hibban, Ed’ıye, No: 960"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Fakirlikten, yoksulluktan ve zilletten sana sığınırım. Haksızlık etmekten ve haksızlığa uğramaktan da sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "Allah’ım! Fakirlikten, yoksulluktan ve zilletten sana sığınırım. Haksızlık etmekten ve haksızlığa uğramaktan da sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}}',true),
('prayer','worship','any','{"tr": {"content": "Ey Rabbimiz! Üzerimize sabır yağdır ve Müslüman olarak bizim canımızı al.", "source": "A’râf, 7/126"}, "en": {"content": "Ey Rabbimiz! Üzerimize sabır yağdır ve Müslüman olarak bizim canımızı al.", "source": "A’râf, 7/126"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Bizi ve imanda bizden önce olan din kardeşlerimizi mağfiret eyle ve kalbimizde mü’minler için kin ve haset bırakma. Ey Rabbimiz! Sen çok şefkat ve çok merhamet sahibisin.", "source": "Haşr, 59/10"}, "en": {"content": "Ey Rabbimiz! Bizi ve imanda bizden önce olan din kardeşlerimizi mağfiret eyle ve kalbimizde mü’minler için kin ve haset bırakma. Ey Rabbimiz! Sen çok şefkat ve çok merhamet sahibisin.", "source": "Haşr, 59/10"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Bizi, inkâr edenler için bir sınama konusu yapma. Bizi bağışla ey Rabbimiz! Çünkü kudret ve hikmet sahibi olan ancak sensin.", "source": "Mümtehine, 60/5"}, "en": {"content": "Rabbimiz! Bizi, inkâr edenler için bir sınama konusu yapma. Bizi bağışla ey Rabbimiz! Çünkü kudret ve hikmet sahibi olan ancak sensin.", "source": "Mümtehine, 60/5"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Peygamberlerin aracılığıyla bize vaad ettiklerini ver bize; kıyamet gününde bizi rezil etme. Sen asla sözünden dönmezsin.", "source": "Âl-i İmrân, 3/194"}, "en": {"content": "Rabbimiz! Peygamberlerin aracılığıyla bize vaad ettiklerini ver bize; kıyamet gününde bizi rezil etme. Sen asla sözünden dönmezsin.", "source": "Âl-i İmrân, 3/194"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Bizi doğru yola eriştirdikten sonra kalplerimizi saptırma, bize tarafından bir rahmet bağışla. Hiç kuşku yok, lütfu bol olan yalnız sensin.", "source": "Âl-i İmrân, 3/8"}, "en": {"content": "Rabbimiz! Bizi doğru yola eriştirdikten sonra kalplerimizi saptırma, bize tarafından bir rahmet bağışla. Hiç kuşku yok, lütfu bol olan yalnız sensin.", "source": "Âl-i İmrân, 3/8"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Senden hidayet, takva, iffet ve gönül zenginliği istiyorum.", "source": "Müslim, Duâ, 72"}, "en": {"content": "Allah’ım! Senden hidayet, takva, iffet ve gönül zenginliği istiyorum.", "source": "Müslim, Duâ, 72"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbim! Beni ve kardeşimi bağışla, bizi rahmetine gark eyle! Sen merhametlilerin en merhametlisisin.", "source": "A’râf, 7/151"}, "en": {"content": "Ey Rabbim! Beni ve kardeşimi bağışla, bizi rahmetine gark eyle! Sen merhametlilerin en merhametlisisin.", "source": "A’râf, 7/151"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Bana öğrettiğin şeyleri hakkımda faydalı eyle, bana fayda verecek şeyleri öğret; beni, bana fayda verecek ilim ile nasiplendir.", "source": "Hâkim, Deavât, No: 1879, I"}, "en": {"content": "Allah’ım! Bana öğrettiğin şeyleri hakkımda faydalı eyle, bana fayda verecek şeyleri öğret; beni, bana fayda verecek ilim ile nasiplendir.", "source": "Hâkim, Deavât, No: 1879, I"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Günahlarımın küçüğünü büyüğünü, öncesini sonunu, açığını ve gizlisini, hepsini bağışla.", "source": "Müslim, Salât, 216"}, "en": {"content": "Allah’ım! Günahlarımın küçüğünü büyüğünü, öncesini sonunu, açığını ve gizlisini, hepsini bağışla.", "source": "Müslim, Salât, 216"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Hesap kurulacağı gün beni, anamı, babamı ve mü’minleri bağışla!", "source": "İbrahim, 14/41"}, "en": {"content": "Rabbimiz! Hesap kurulacağı gün beni, anamı, babamı ve mü’minleri bağışla!", "source": "İbrahim, 14/41"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Ey Rabbimiz! Bize gökten öyle bir sofra indir ki, ilk gelenimizden son gelenimize kadar bizler için bir bayram ziyafeti ve senden bir işaret olsun. Bizi rızıklandır, sen rızık verenlerin en hayırlısısın.", "source": "Mâide, 5/114"}, "en": {"content": "Allah’ım! Ey Rabbimiz! Bize gökten öyle bir sofra indir ki, ilk gelenimizden son gelenimize kadar bizler için bir bayram ziyafeti ve senden bir işaret olsun. Bizi rızıklandır, sen rızık verenlerin en hayırlısısın.", "source": "Mâide, 5/114"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Lütfun, rahmetin, bereketin ve rızkından bana aç, bolca ihsan eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "Allah’ım! Lütfun, rahmetin, bereketin ve rızkından bana aç, bolca ihsan eyle.", "source": "Hâkim, Deavât, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Yolculuğun yorgunluk ve sıkıntılarından, yoldan kötü bir şekilde dönmekten, iyi hâllerden kötü hâllere düşmekten, mazlumun bedduasından, mala ve aileye gelecek kötülüklerden sana sığınırım.", "source": "Müslim, Hac, 426"}, "en": {"content": "Allah’ım! Yolculuğun yorgunluk ve sıkıntılarından, yoldan kötü bir şekilde dönmekten, iyi hâllerden kötü hâllere düşmekten, mazlumun bedduasından, mala ve aileye gelecek kötülüklerden sana sığınırım.", "source": "Müslim, Hac, 426"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Günahlarımı kar ve dolu suyu ile yıka ve beyaz elbiseyi kirden temizler gibi kalbimi hatalardan arındır.", "source": "Buhârî, Deavât, 39"}, "en": {"content": "Allah’ım! Günahlarımı kar ve dolu suyu ile yıka ve beyaz elbiseyi kirden temizler gibi kalbimi hatalardan arındır.", "source": "Buhârî, Deavât, 39"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bildiğin günahlarımı bağışlamanı istiyorum. Bildiğin her türlü hayırdan istiyorum. Bildiğin bütün şeylerden sana sığınıyorum. Süphesiz sen gaybı/gizli olan şeyleri en iyi bilensin.", "source": "Hâkim, Deavât, No: 1872"}, "en": {"content": "Allah’ım! Bildiğin günahlarımı bağışlamanı istiyorum. Bildiğin her türlü hayırdan istiyorum. Bildiğin bütün şeylerden sana sığınıyorum. Süphesiz sen gaybı/gizli olan şeyleri en iyi bilensin.", "source": "Hâkim, Deavât, No: 1872"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Açlıktan sana sığınırım. Çünkü açlık ne kötü bir arkadaştır. Hainlikten de sana sığınırım. Çünkü hainlik ne kötü bir sırdaştır.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "Allah’ım! Açlıktan sana sığınırım. Çünkü açlık ne kötü bir arkadaştır. Hainlikten de sana sığınırım. Çünkü hainlik ne kötü bir sırdaştır.", "source": "Ebû Dâvûd, Vitr, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Beni bağışla, bana hidayet nasip eyle, bana rızık ver, beni afiyette daim eyle ve bana merhamet et.", "source": "Müslim, Zikir ve Duâ, 35"}, "en": {"content": "Allah’ım! Beni bağışla, bana hidayet nasip eyle, bana rızık ver, beni afiyette daim eyle ve bana merhamet et.", "source": "Müslim, Zikir ve Duâ, 35"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bize imanı sevdir, kalplerimizi imanla süsle. Bize küfrü, itaatsizliği ve isyanı sevdirme, kerih göster, bizi doğru yolu bulanlardan eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "Allah’ım! Bize imanı sevdir, kalplerimizi imanla süsle. Bize küfrü, itaatsizliği ve isyanı sevdirme, kerih göster, bizi doğru yolu bulanlardan eyle.", "source": "Hâkim, Deavât, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! İndirdiğine inandık ve Peygambere tâbi olduk; artık bizi şahitlerle beraber yaz.", "source": "Âl-i İmrân, 3/53"}, "en": {"content": "Rabbimiz! İndirdiğine inandık ve Peygambere tâbi olduk; artık bizi şahitlerle beraber yaz.", "source": "Âl-i İmrân, 3/53"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Bizi sana teslim olanlardan eyle, soyumuzdan da sana teslim olacak bir ümmet çıkar. Bize ibadet usullerimizi göster, tevbemizi kabul et. Şüphesiz tövbeleri kabul eden, merhameti bol olan sensin.", "source": "Bakara, 2/128"}, "en": {"content": "Ey Rabbimiz! Bizi sana teslim olanlardan eyle, soyumuzdan da sana teslim olacak bir ümmet çıkar. Bize ibadet usullerimizi göster, tevbemizi kabul et. Şüphesiz tövbeleri kabul eden, merhameti bol olan sensin.", "source": "Bakara, 2/128"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Ciddi ve şaka yollu yaptıklarımı, yanlışlıkla ve bilerek işlediğim günahlarımı affeyle! Bütün bu kusurların bende bulunduğunu itiraf ederim.", "source": "Müslim, Zikir, 70"}, "en": {"content": "Allah’ım! Ciddi ve şaka yollu yaptıklarımı, yanlışlıkla ve bilerek işlediğim günahlarımı affeyle! Bütün bu kusurların bende bulunduğunu itiraf ederim.", "source": "Müslim, Zikir, 70"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Beni amellerin ve ahlakın en güzeline kavuştur. Onların en güzeline ancak sen ulaştırırsın. Beni kötü işlerden ve kötü ahlaktan muhafaza et. Bunlardan ancak sen koruyabilirsin.", "source": "Nesâî, İftitâh, 16"}, "en": {"content": "Allah’ım! Beni amellerin ve ahlakın en güzeline kavuştur. Onların en güzeline ancak sen ulaştırırsın. Beni kötü işlerden ve kötü ahlaktan muhafaza et. Bunlardan ancak sen koruyabilirsin.", "source": "Nesâî, İftitâh, 16"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Şüphesiz ben nefsime çok zulmettim, günahları bağışlayacak olan yalnız sensin. Öyleyse katından bir af ile beni bağışla. Bana merhamet et, çünkü bağışlaması ve rahmeti çok olan sadece sensin.", "source": "Buhari, Ezan, 149"}, "en": {"content": "Allah’ım! Şüphesiz ben nefsime çok zulmettim, günahları bağışlayacak olan yalnız sensin. Öyleyse katından bir af ile beni bağışla. Bana merhamet et, çünkü bağışlaması ve rahmeti çok olan sadece sensin.", "source": "Buhari, Ezan, 149"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey mülkün gerçek sahibi olan Allah’ım! Mülkü dilediğine verirsin, dilediğinden çekip alırsın. Dilediğini yüceltirsin, dilediğini de alçaltırsın. Her türlü iyilik senin elindedir. Hiç kuşku yok sen her şeye kâdirsin.", "source": "Âl-i İmrân, 3/36"}, "en": {"content": "Ey mülkün gerçek sahibi olan Allah’ım! Mülkü dilediğine verirsin, dilediğinden çekip alırsın. Dilediğini yüceltirsin, dilediğini de alçaltırsın. Her türlü iyilik senin elindedir. Hiç kuşku yok sen her şeye kâdirsin.", "source": "Âl-i İmrân, 3/36"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bana verdiğin rızık konusunda beni kanaat sahibi yap ve o rızkımı bereketli kıl. Zayi olan her nimetin daha hayırlısını bana ihsan eyle.", "source": "Hâkim, Deavât, No: 1878"}, "en": {"content": "Allah’ım! Bana verdiğin rızık konusunda beni kanaat sahibi yap ve o rızkımı bereketli kıl. Zayi olan her nimetin daha hayırlısını bana ihsan eyle.", "source": "Hâkim, Deavât, No: 1878"}}',true),
('prayer','hope','any','{"tr": {"content": "Allah’ım! Açıklarımı ört, korkularımı gider ve bana güven ver. Allah’ım! Ayıplarımı ört ve korkularımı gider.", "source": "Hâkim, Deavât, No: 1902, I"}, "en": {"content": "Allah’ım! Açıklarımı ört, korkularımı gider ve bana güven ver. Allah’ım! Ayıplarımı ört ve korkularımı gider.", "source": "Hâkim, Deavât, No: 1902, I"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Tövbelerimizi kabul eyle, süphesiz ki sen tövbeleri çok kabul edensin, çok merhametlisin. Bizi nimetlerine şükredenler, nimetlerinle seni övenler, verdiğin nimetleri kabul edenlerden eyle ve bize nimetlerin devamını ihsan eyle.", "source": "Hâkim, Temin, No: 977"}, "en": {"content": "Allah’ım! Tövbelerimizi kabul eyle, süphesiz ki sen tövbeleri çok kabul edensin, çok merhametlisin. Bizi nimetlerine şükredenler, nimetlerinle seni övenler, verdiğin nimetleri kabul edenlerden eyle ve bize nimetlerin devamını ihsan eyle.", "source": "Hâkim, Temin, No: 977"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Rabbim!) İnsanların diriltileceği gün ve Allah’a temiz bir kalple gelenler dışında malın da çocukların da fayda vermeyeceği gün beni mahcup etme!", "source": "Şu’arâ, 26/87-89"}, "en": {"content": "(Rabbim!) İnsanların diriltileceği gün ve Allah’a temiz bir kalple gelenler dışında malın da çocukların da fayda vermeyeceği gün beni mahcup etme!", "source": "Şu’arâ, 26/87-89"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bütün işlerimdeki ölçüsüzlüğümü, cahilliğimi ve hatamı bağışla. Sen bunları benden daha iyi biliyorsun.", "source": "Buhari, Deavât, 60"}, "en": {"content": "Allah’ım! Bütün işlerimdeki ölçüsüzlüğümü, cahilliğimi ve hatamı bağışla. Sen bunları benden daha iyi biliyorsun.", "source": "Buhari, Deavât, 60"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey kalpleri evirip çeviren (Allah’ım!) Benim kalbimi dinin üzere sabit kıl.", "source": "Tirmizî, Deavât, 89"}, "en": {"content": "Ey kalpleri evirip çeviren (Allah’ım!) Benim kalbimi dinin üzere sabit kıl.", "source": "Tirmizî, Deavât, 89"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Sen bunu boş yere yaratmadın, seni tenzih ve takdis ederiz. Bizi cehennem azabından koru!", "source": "Âl-i İmrân, 3/191"}, "en": {"content": "Rabbimiz! Sen bunu boş yere yaratmadın, seni tenzih ve takdis ederiz. Bizi cehennem azabından koru!", "source": "Âl-i İmrân, 3/191"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bana doğru olanı ilham et ve beni nefsimin şerrinden koru.", "source": "Tirmizî, Deavât, 70"}, "en": {"content": "Allah’ım! Bana doğru olanı ilham et ve beni nefsimin şerrinden koru.", "source": "Tirmizî, Deavât, 70"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbim! Bana tarafından temiz bir nesil ihsan eyle! Kuşkusuz sen duayı işitmektesin.", "source": "Âl-i İmrân, 3/38"}, "en": {"content": "Rabbim! Bana tarafından temiz bir nesil ihsan eyle! Kuşkusuz sen duayı işitmektesin.", "source": "Âl-i İmrân, 3/38"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Ancak sana dayandık, sana yöneldik. Dönüş de ancak sanadır.", "source": "Mümtehine, 60/4"}, "en": {"content": "Rabbimiz! Ancak sana dayandık, sana yöneldik. Dönüş de ancak sanadır.", "source": "Mümtehine, 60/4"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Biz gerçekten iman ettik, günahlarımızı bağışla, bizi ateş azabından koru", "source": "Âl-i İmrân, 3/16"}, "en": {"content": "Ey Rabbimiz! Biz gerçekten iman ettik, günahlarımızı bağışla, bizi ateş azabından koru", "source": "Âl-i İmrân, 3/16"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Yaşamak benim için hayırlı olduğu sürece beni yaşat. Ölmek benim için hayırlı olduğunda da benim canımı al!", "source": "Buhârî, Merdâ, 19"}, "en": {"content": "Allah’ım! Yaşamak benim için hayırlı olduğu sürece beni yaşat. Ölmek benim için hayırlı olduğunda da benim canımı al!", "source": "Buhârî, Merdâ, 19"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Senden hayırlı olan işleri yapmayı, aklın ve dinin çirkin gördüğü şeyleri terk etmeyi ve fakirlerin sevgisini istiyorum.", "source": "Mâlik, Duâ, No: 508"}, "en": {"content": "Allah’ım! Senden hayırlı olan işleri yapmayı, aklın ve dinin çirkin gördüğü şeyleri terk etmeyi ve fakirlerin sevgisini istiyorum.", "source": "Mâlik, Duâ, No: 508"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Senden düzgün bir yaşantı, temiz bir ölüm ve rezil rüsva olmadan sana dönebilmeyi istiyorum.", "source": "İbn Ebu Şeybe, Duâ, 1, No: 29134"}, "en": {"content": "Allah’ım! Senden düzgün bir yaşantı, temiz bir ölüm ve rezil rüsva olmadan sana dönebilmeyi istiyorum.", "source": "İbn Ebu Şeybe, Duâ, 1, No: 29134"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Lütfundan bize rızık ver, bizi rızkından mahrum etme, bize verdiğin rızıkları bizim için bereketli yap, katında bulunan nimetlere rağbetimizi arttır ve bizi gönül zengini eyle.", "source": "İbn Ebu Şeybe, Duâ, 42"}, "en": {"content": "Allah’ım! Lütfundan bize rızık ver, bizi rızkından mahrum etme, bize verdiğin rızıkları bizim için bereketli yap, katında bulunan nimetlere rağbetimizi arttır ve bizi gönül zengini eyle.", "source": "İbn Ebu Şeybe, Duâ, 42"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbim! Onlar (anne ve babam) nasıl küçüklükte beni şefkatle eğitip yetiştirdilerse şimdi sen de onlara merhamet göster.", "source": "İsrâ, 17/24"}, "en": {"content": "Rabbim! Onlar (anne ve babam) nasıl küçüklükte beni şefkatle eğitip yetiştirdilerse şimdi sen de onlara merhamet göster.", "source": "İsrâ, 17/24"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Gazabından rızana, cezandan affına sığınırım. Senden sana sığınırım. sana tüm övgüleri saysam yine de bitiremem. Sen kendini nasıl övdüysen öylesin.", "source": "Müslim, Salât, 222"}, "en": {"content": "Allah’ım! Gazabından rızana, cezandan affına sığınırım. Senden sana sığınırım. sana tüm övgüleri saysam yine de bitiremem. Sen kendini nasıl övdüysen öylesin.", "source": "Müslim, Salât, 222"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah seni yarattıklarından uzaklaştırdığı zaman bil ki, sana dostluğunun kapısını açmak istiyordur. Ataullah İskenderî “Allah’ım! (Haktan) ayrılmaktan, iki yüzlülükten ve kötü ahlaktan sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "Allah seni yarattıklarından uzaklaştırdığı zaman bil ki, sana dostluğunun kapısını açmak istiyordur. Ataullah İskenderî “Allah’ım! (Haktan) ayrılmaktan, iki yüzlülükten ve kötü ahlaktan sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Rahmetinin gereklerini, mağfiretinin sürekliliğini, her türlü günahtan uzak ve salim olmayı, her türlü iyilik ve nimetleri, cennete girerek felaha ermeyi, yardımınla cehennem ateşinden kurtulmayı istiyorum.", "source": "Hâkim, Deavât, No: 1925"}, "en": {"content": "Allah’ım! Rahmetinin gereklerini, mağfiretinin sürekliliğini, her türlü günahtan uzak ve salim olmayı, her türlü iyilik ve nimetleri, cennete girerek felaha ermeyi, yardımınla cehennem ateşinden kurtulmayı istiyorum.", "source": "Hâkim, Deavât, No: 1925"}}',true),
('prayer','hope','any','{"tr": {"content": "Rabbimiz! Nurumuzu arttır, eksiltme ve bizi bağışla. Şüphesiz senin her şeye gücün yeter.", "source": "Tahrîm, 66/8"}, "en": {"content": "Rabbimiz! Nurumuzu arttır, eksiltme ve bizi bağışla. Şüphesiz senin her şeye gücün yeter.", "source": "Tahrîm, 66/8"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Helal olan nimetlerinle yetinmemi, haramlardan müstağni olmamı ihsan eyle, fazlı kereminle beni senden başkasına muhtaç eyleme.", "source": "Hâkim, Deavât, No: 1973"}, "en": {"content": "Allah’ım! Helal olan nimetlerinle yetinmemi, haramlardan müstağni olmamı ihsan eyle, fazlı kereminle beni senden başkasına muhtaç eyleme.", "source": "Hâkim, Deavât, No: 1973"}}',true),
('prayer','hope','any','{"tr": {"content": "Allah’ım! Kederden, üzüntüden, tembellikten, cimrilikten, korkaklıktan, borç yükünden ve halkın galeyana gelerek taşkınlığından sana sığınırım.", "source": "Nesâî, İstiâze, 25"}, "en": {"content": "Allah’ım! Kederden, üzüntüden, tembellikten, cimrilikten, korkaklıktan, borç yükünden ve halkın galeyana gelerek taşkınlığından sana sığınırım.", "source": "Nesâî, İstiâze, 25"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Allah’ım! Seni zikretmek, sana şükretmek ve sana güzelce ibadet etmek için bana yardım et.", "source": "Ebû Dâvûd, Tefrîu Ebvâbi’l-Vitr, 26"}, "en": {"content": "Allah’ım! Seni zikretmek, sana şükretmek ve sana güzelce ibadet etmek için bana yardım et.", "source": "Ebû Dâvûd, Tefrîu Ebvâbi’l-Vitr, 26"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Biz kendimize zulmettik. Eğer bizi bağışlamaz, bize acımazsan mutlaka ziyan edenlerden oluruz!", "source": "A’râf, 7/23"}, "en": {"content": "Ey Rabbimiz! Biz kendimize zulmettik. Eğer bizi bağışlamaz, bize acımazsan mutlaka ziyan edenlerden oluruz!", "source": "A’râf, 7/23"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Nimetlerinin yok olmasından, sağlığımın bozulmasından, ansızın gelecek cezandan ve öfkene sebep olan her şeyden sana sığınırım.", "source": "Müslim, Rikâk, 96"}, "en": {"content": "Allah’ım! Nimetlerinin yok olmasından, sağlığımın bozulmasından, ansızın gelecek cezandan ve öfkene sebep olan her şeyden sana sığınırım.", "source": "Müslim, Rikâk, 96"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Faydasız ilimden, huşu duymayan kalpten, doymayan nefisten ve kabul edilmeyen duadan sana sığınırım.", "source": "Nesâî, İstiâze, 64"}, "en": {"content": "Allah’ım! Faydasız ilimden, huşu duymayan kalpten, doymayan nefisten ve kabul edilmeyen duadan sana sığınırım.", "source": "Nesâî, İstiâze, 64"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kullarını mahşerde topladığın veya mahşerde kaldırdığın gün beni azabından koru.", "source": "Tirmizî, Deavât, 18"}, "en": {"content": "Allah’ım! Kullarını mahşerde topladığın veya mahşerde kaldırdığın gün beni azabından koru.", "source": "Tirmizî, Deavât, 18"}}',true),
('prayer','prayer','any','{"tr": {"content": "Bizi yedirip içiren ve bizi Müslümanlardan eyleyen Allah’a hamdolsun.", "source": "Tirmizî, Deavât, 56"}, "en": {"content": "Bizi yedirip içiren ve bizi Müslümanlardan eyleyen Allah’a hamdolsun.", "source": "Tirmizî, Deavât, 56"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Rabbim!) Arkadan gelecekler içinde iyilikle anılmayı bana nasip eyle!", "source": "Şu’arâ, 26/84"}, "en": {"content": "(Rabbim!) Arkadan gelecekler içinde iyilikle anılmayı bana nasip eyle!", "source": "Şu’arâ, 26/84"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Bana öğrettiğin ilim ile beni faydalandır, bana fayda verecek ilmi bana öğret ve benim ilmimi arttır. Her hâl üzere Allah’a hamdolsun. Cehennem ehlinin hâlinden Allah’a sığınırım.", "source": "Tirmizî, Deavât, 130"}, "en": {"content": "Allah’ım! Bana öğrettiğin ilim ile beni faydalandır, bana fayda verecek ilmi bana öğret ve benim ilmimi arttır. Her hâl üzere Allah’a hamdolsun. Cehennem ehlinin hâlinden Allah’a sığınırım.", "source": "Tirmizî, Deavât, 130"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Benim yaratılışımı güzel kıldığın gibi ahlakımı da güzelleştir...", "source": "İbn Hanbel, I, 403"}, "en": {"content": "Allah’ım! Benim yaratılışımı güzel kıldığın gibi ahlakımı da güzelleştir...", "source": "İbn Hanbel, I, 403"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Allah’ım seni zikretmek, sana şükretmek, sana güzelce ibadet etmekte bize yardım et.", "source": "İbn Hanbel, II, 299"}, "en": {"content": "Allah’ım seni zikretmek, sana şükretmek, sana güzelce ibadet etmekte bize yardım et.", "source": "İbn Hanbel, II, 299"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Rabbim) Beni, naim cennetine girenlerden eyle!", "source": "Şu’arâ, 26/85"}, "en": {"content": "(Rabbim) Beni, naim cennetine girenlerden eyle!", "source": "Şu’arâ, 26/85"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Rabbim! Bana ve anne-babama lütfettiğin nimete şükretmeye, razı olacağın işleri yapmaya beni muvaffak kıl. Benden gelecek nesli hayırlı eyle, pişmanlıkla dönüp senin kapına başvurmaktayım ve ben süphesiz sana boyun eğenlerdenim.", "source": "Ahkâf, 46/15"}, "en": {"content": "Rabbim! Bana ve anne-babama lütfettiğin nimete şükretmeye, razı olacağın işleri yapmaya beni muvaffak kıl. Benden gelecek nesli hayırlı eyle, pişmanlıkla dönüp senin kapına başvurmaktayım ve ben süphesiz sana boyun eğenlerdenim.", "source": "Ahkâf, 46/15"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kalbimde nur, gözümde nur, kulağımda nur, sağımda nur, solumda nur, üstümde nur, altımda nur, önümde nur var eyle, benim nurumu artır.", "source": "Müslim, Müsâfirîn, 181"}, "en": {"content": "Allah’ım! Kalbimde nur, gözümde nur, kulağımda nur, sağımda nur, solumda nur, üstümde nur, altımda nur, önümde nur var eyle, benim nurumu artır.", "source": "Müslim, Müsâfirîn, 181"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ödül ve ceza gününün tek hâkimi. (Rabbimiz!) Ancak sana kulluk eder ve yalnız senden yardım dileriz.", "source": "Fâtiha, 1/4-5"}, "en": {"content": "Ödül ve ceza gününün tek hâkimi. (Rabbimiz!) Ancak sana kulluk eder ve yalnız senden yardım dileriz.", "source": "Fâtiha, 1/4-5"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Hesap kurulacağı gün beni, anamı, babamı ve müminleri bağışla!", "source": "İbrahim, 14/41"}, "en": {"content": "Rabbimiz! Hesap kurulacağı gün beni, anamı, babamı ve müminleri bağışla!", "source": "İbrahim, 14/41"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Şüphesiz ki sen gizlediğimizi de açıkladığımızı da bilirsin. Yerde ve gökte hiçbir şey Allah’a gizli kalmaz.", "source": "İbrahim, 14/38"}, "en": {"content": "Rabbimiz! Şüphesiz ki sen gizlediğimizi de açıkladığımızı da bilirsin. Yerde ve gökte hiçbir şey Allah’a gizli kalmaz.", "source": "İbrahim, 14/38"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! (Haktan) ayrılmaktan, iki yüzlülükten ve kötü ahlaktan sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "Allah’ım! (Haktan) ayrılmaktan, iki yüzlülükten ve kötü ahlaktan sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Rahmetinin gereklerini, mağfiretinin sürekliliğini, her türlü günahtan uzak ve salim olmayı, her türlü iyilik ve nimetleri, cennete girerek felaha ermeyi, yardımınla cehennem ateşinden kurtulmayı istiyorum.", "source": "Hâkim, Deavât, No: 1925"}, "en": {"content": "Allah’ım! Rahmetinin gereklerini, mağfiretinin sürekliliğini, her türlü günahtan uzak ve salim olmayı, her türlü iyilik ve nimetleri, cennete girerek felaha ermeyi, yardımınla cehennem ateşinden kurtulmayı istiyorum.", "source": "Hâkim, Deavât, No: 1925"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Rabbim! Bana ve anne-babama lutfettiğin nimete şükretmeye, razı olacağın işleri yapmaya beni muvaffak kıl. Benden gelecek nesli hayırlı eyle, pişmanlıkla dönüp senin kapına başvurmaktayım ve ben, süphesiz sana boyun eğenlerdenim.", "source": "Ahkâf, 46/15"}, "en": {"content": "Rabbim! Bana ve anne-babama lutfettiğin nimete şükretmeye, razı olacağın işleri yapmaya beni muvaffak kıl. Benden gelecek nesli hayırlı eyle, pişmanlıkla dönüp senin kapına başvurmaktayım ve ben, süphesiz sana boyun eğenlerdenim.", "source": "Ahkâf, 46/15"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sen affedicisin, Kerim’sin, affı seversin, beni affet", "source": "Tirmizî, Deavât, 84"}, "en": {"content": "Allah’ım! Sen affedicisin, Kerim’sin, affı seversin, beni affet", "source": "Tirmizî, Deavât, 84"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah diyene Canım kurban, başı secdede, İki büklüm, Allah diyene Akıl, kırık kanadı hiçin; Derdi gücü ‘nasıl’ ve ‘niçin’... Bağlı, perçin üstüne perçin, Benim gönlüm Allah diyene... Necip Fazıl Kısakürek “Allah’ım! Cehenneme götüren fitneden, cehennemin azabından, zenginliğin ve fakirliğin şerrinden sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "Allah diyene Canım kurban, başı secdede, İki büklüm, Allah diyene Akıl, kırık kanadı hiçin; Derdi gücü ‘nasıl’ ve ‘niçin’... Bağlı, perçin üstüne perçin, Benim gönlüm Allah diyene... Necip Fazıl Kısakürek “Allah’ım! Cehenneme götüren fitneden, cehennemin azabından, zenginliğin ve fakirliğin şerrinden sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allahsıza hiçlik oldu Allah, Varlıktan edince gönlü ikrah. Hasan Âli Yücel “Allah’ım! Gidip ebedî yaşayacağım ahiret hayatımı benim için hayırlı eyle. Hayatımda her türlü hayrı ziyadesiyle ihsan eyle. Ölümümü de her türlü şerlerden muhafaza eyle.", "source": "Müslim, Duâ, 71"}, "en": {"content": "Allahsıza hiçlik oldu Allah, Varlıktan edince gönlü ikrah. Hasan Âli Yücel “Allah’ım! Gidip ebedî yaşayacağım ahiret hayatımı benim için hayırlı eyle. Hayatımda her türlü hayrı ziyadesiyle ihsan eyle. Ölümümü de her türlü şerlerden muhafaza eyle.", "source": "Müslim, Duâ, 71"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Tövbelerimizi kabul eyle, şüphesiz ki sen tövbeleri çok kabul edensin, çok merhametlisin. Bizi nimetlerine şükredenler, nimetlerinle seni övenler, verdiğin nimetleri kabul edenlerden eyle ve bize nimetlerin devamını ihsan eyle.", "source": "Hâkim, Temin, No: 977"}, "en": {"content": "Allah’ım! Tövbelerimizi kabul eyle, şüphesiz ki sen tövbeleri çok kabul edensin, çok merhametlisin. Bizi nimetlerine şükredenler, nimetlerinle seni övenler, verdiğin nimetleri kabul edenlerden eyle ve bize nimetlerin devamını ihsan eyle.", "source": "Hâkim, Temin, No: 977"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Allah’ım! Senin rahmetini umuyorum, beni göz açıp kapayıncaya kadar", "source": "da olsa"}, "en": {"content": "Ey Allah’ım! Senin rahmetini umuyorum, beni göz açıp kapayıncaya kadar", "source": "da olsa"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey hoca bir dem kulak ol aç gözün Bilmeğe taleb edersen kendi özün Kaygusuz Abdal “(Rabbim) Beni, naim cennetine girenlerden eyle!", "source": "Şu’arâ, 26/85"}, "en": {"content": "Ey hoca bir dem kulak ol aç gözün Bilmeğe taleb edersen kendi özün Kaygusuz Abdal “(Rabbim) Beni, naim cennetine girenlerden eyle!", "source": "Şu’arâ, 26/85"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’a lâyık olur Uyanır gafletden açar gözünü Vezn ile mîzâna dartar sözünü Kaygusuz Abdal “Allah’ım! Lütfun, rahmetin, bereketin ve rızkından bana aç, bolca ihsan eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "Allah’a lâyık olur Uyanır gafletden açar gözünü Vezn ile mîzâna dartar sözünü Kaygusuz Abdal “Allah’ım! Lütfun, rahmetin, bereketin ve rızkından bana aç, bolca ihsan eyle.", "source": "Hâkim, Deavât, No: 1868"}}',true);
